window.kbPageData["views/entry/k-7d44fefcbaab9e38"] = {"key":"entry/k-7d44fefcbaab9e38","state":{"route":"entry/k-7d44fefcbaab9e38"},"node":{"id":"k-7d44fefcbaab9e38","mode":"k","title":"平均数的增长率","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["平均数的增长率等于总量增速与数量增速之差除以一加数量增速","平均数增速的方向"],"qs":["国考 2025 行政执法 行测#129","国考 2025 行政执法 行测#130"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"directorySummary":"平均数的增长率是现期平均数相对基期平均数的变化比例。若两期统计口径一致，且分子、分母在两期均为正，分子和分母的增长率分别为 a 和 b，则平均数增长率为 (a−b)/(1+b)。","review":{"title":"平均数的增长率","type":"原理与机制","definition":"平均数的增长率是现期平均数相对基期平均数的变化比例。若两期统计口径一致，且分子、分母在两期均为正，分子和分母的增长率分别为 a 和 b，则平均数增长率为 (a−b)/(1+b)。","explanation":"由于 1+b 为正，a 大于、等于或小于 b 分别对应平均数上升、持平或下降。下降率以负值代入。比较多个对象的平均数增长率时，各对象的 1+b 可能不同，须比较完整的比值。","basis":"据关联原题和解析编释。","references":[],"related":["k-ae419c6fcf2d8561"],"examFocus":{"国考 2025 行政执法 行测#129":"用各支付系统的总金额和总笔数同比增速推算每笔金额同比增速，再按推算值排序。","国考 2025 行政执法 行测#130":"用同一支付系统的金额和笔数同比增速推算每笔金额的增速，再与题设阈值比较。"}},"aspects":[{"title":"平均数增长率排序","uses":[{"unit":"Q1","role":"直接考查","use":"以业务金额为分子、业务笔数为分母，算得①至④的平均每笔业务金额同比增速约为 −13.71%、−10.44%、1.26%和44.04%。④的金额和笔数均下降，且笔数降幅更大，每笔金额增速居首。降序为④③②①，选C。","evidence":"按2023年三季度平均每笔业务金额同比增速从高到低排列","qids":["国考 2025 行政执法 行测#129"]}]},{"title":"平均数增长率的阈值核验","uses":[{"unit":"Q2","role":"解题依据","use":"网上支付跨行清算系统的业务金额同比增长5.38%，笔数同比下降0.03%，每笔金额同比增长约5.41%，所以A项可以推出。本题要求选出不能推出的一项，C项所述占比实际约为94.73%，低于95%，故选C。","evidence":"网上支付跨行清算系统处理业务平均每笔金额同比增长了5%以上","qids":["国考 2025 行政执法 行测#130"]}]}]},"questions":{"国考 2025 行政执法 行测#129":{"paper":"国考 2025 行政执法 行测","n":129,"mod":"资料分析","src":["d8efe4e19862104d89c8.pdf",26],"asrc":["e2c4b1970d2b49eac0fd.pdf",41],"card":"65c648b04e3ed700ec565d44","links":[{"id":"k-7d44fefcbaab9e38","role":"解题依据","why":"将总金额和笔数的带符号增速转换为可跨系统比较的每笔金额增速。"}]},"国考 2025 行政执法 行测#130":{"paper":"国考 2025 行政执法 行测","n":130,"mod":"资料分析","src":["d8efe4e19862104d89c8.pdf",26],"asrc":["e2c4b1970d2b49eac0fd.pdf",42],"card":"ac4473bfd0df2e18b4106ea8","links":[{"id":"k-7d44fefcbaab9e38","role":"解题依据","why":"由总金额和业务笔数增速推算每笔金额增速，再核验给定阈值。"}]}},"terms":{"k-ae419c6fcf2d8561":{"id":"k-ae419c6fcf2d8561","mode":"k","type":"原理与机制","title":"平均数同比增长率","qs":[],"count":2}},"references":{},"topics":[],"units":{"k-7d44fefcbaab9e38":[["国考 2025 行政执法 行测#129"],["国考 2025 行政执法 行测#130"]]}};
